.als-page{max-width:980px;margin:0 auto;padding:20px 24px 44px}.als-back{display:inline-flex;margin-bottom:12px;color:#4b8d28;text-decoration:none;font-size:11px}.als-page h1{margin:0 0 24px;color:#0b1933;font-size:30px}.als-page h2{margin:0 0 4px;color:#0b3142;font-size:17px}.als-sub{margin:0 0 18px;color:#6f7b90;font-size:11px}.als-card{border:1px solid #dce4eb;border-radius:8px;background:#fff;overflow:hidden}.als-card-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 14px;border-bottom:1px solid #dfe6eb}.als-card-head strong{font-size:12px;color:#0b3142}.als-count{display:inline-grid;place-items:center;min-width:20px;height:18px;padding:0 6px;border-radius:999px;background:#edf0f1;color:#60727e;font-size:9px}.als-email{margin-top:2px;color:#6f7b90;font-size:9px}.als-btn{min-height:32px;display:inline-flex;align-items:center;justify-content:center;padding:0 12px;border:1px solid #d9e2e9;border-radius:8px;background:#fff;color:#df4f3f;font:inherit;font-size:10px;font-weight:700;cursor:pointer}.als-row{display:grid;grid-template-columns:36px minmax(0,1fr) auto;gap:10px;align-items:center;padding:12px 14px;border-bottom:1px solid #e7ecf0}.als-row:last-child{border-bottom:0}.als-icon{width:30px;height:30px;display:grid;place-items:center;border-radius:7px;background:#f1f0ed;color:#1d4655}.als-name{font-size:11px;font-weight:700;color:#183848}.als-meta{margin-top:3px;color:#71808d;font-size:9px}.als-online{color:#2f8c25}.als-empty,.als-loading{padding:28px;text-align:center;color:#6f7b90;font-size:11px}.als-btn.loading{opacity:.65;pointer-events:none}.als-btn.loading:before{content:"";width:11px;height:11px;margin-right:6px;border:2px dotted currentColor;border-radius:50%;animation:s .75s linear infinite}@keyframes s{to{transform:rotate(360deg)}}
