<div class="als-page"><a class="als-back" href="team.php">‹ &nbsp; Manage team</a><h1>Active Login Sessions</h1><div id="sessionContent" class="als-loading">Loading active sessions...</div></div>
<script>
(function(){'use strict';var csrf=<?= json_encode($csrfToken,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>,api='api/team.php',userId=<?= (int)$targetUserId ?>;function E(id){return document.getElementById(id)}function esc(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;')}function toast(t,m){if(window.fieldplxToast)window.fieldplxToast(t,m)}function req(fd){fd.append('csrf_token',csrf);return fetch(api,{method:'POST',body:fd,credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json'}}).then(function(r){return r.text().then(function(x){var d;try{d=JSON.parse(x)}catch(e){throw new Error('Invalid server response.')}if(!r.ok||!d.success)throw new Error(d.message||'Request failed.');return d})})}function ago(v){if(!v)return 'Unknown';var d=new Date(String(v).replace(' ','T')),n=(Date.now()-d.getTime())/1000;if(isNaN(n))return v;if(n<60)return 'just now';if(n<3600)return Math.floor(n/60)+' min. ago';if(n<86400)return Math.floor(n/3600)+' hr. ago';return Math.floor(n/86400)+' day(s) ago'}function device(r){var n=String(r.device_name||'').trim();return n||String(r.platform||'Other').replace(/^./,function(c){return c.toUpperCase()})}
function load(){var f=new FormData();f.append('action','sessions');f.append('user_id',String(userId));req(f).then(function(d){var m=d.member||{},rows=d.sessions||[],name=((m.first_name||'')+' '+(m.last_name||'')).trim();var h='<h2>'+esc(name||'Team member')+'</h2><p class="als-sub">These devices are currently signed in to FieldPlx as '+esc(name||'this team member')+'. Sign out anything that looks unfamiliar.</p><section class="als-card"><div class="als-card-head"><div><strong>Active sessions <span class="als-count">'+rows.length+'</span></strong><div class="als-email">'+esc(m.email||'')+'</div></div><button class="als-btn" id="signAll" '+(!rows.length?'disabled':'')+'>Sign out all sessions</button></div>';
if(!rows.length)h+='<div class="als-empty">No active device sessions found.</div>';else rows.forEach(function(r){h+='<div class="als-row"><div class="als-icon">▣</div><div><div class="als-name">'+esc(device(r))+'</div><div class="als-meta">'+esc(String(r.platform||'Other'))+' · IP '+esc(r.last_ip_address||'Unknown')+' · <span class="als-online">●</span> '+esc(ago(r.last_seen_at||r.created_at))+'</div></div><button class="als-btn" data-sign="'+Number(r.id)+'">Sign out</button></div>'});h+='</section>';E('sessionContent').className='';E('sessionContent').innerHTML=h;var all=E('signAll');if(all)all.onclick=function(){sign('signout_all',0,this)};document.querySelectorAll('[data-sign]').forEach(function(b){b.onclick=function(){sign('signout_session',Number(b.getAttribute('data-sign')),b)}})}).catch(function(e){E('sessionContent').innerHTML='<div class="als-empty">Unable to load active sessions.</div>';toast('error',e.message)})}
function sign(action,id,b){var f=new FormData();f.append('action',action);f.append('user_id',String(userId));if(id)f.append('device_id',String(id));b.disabled=true;b.classList.add('loading');req(f).then(function(d){toast('success',d.message);load()}).catch(function(e){toast('error',e.message);b.disabled=false;b.classList.remove('loading')})}if(userId<=0){E('sessionContent').innerHTML='<div class="als-empty">No team member selected.</div>'}else load();})();
</script>
